values (md5('PE-010:policy:dress_socks:1')::uuid, 'PE-010', 'https://www.kidzatplay.ca/contact', '2026-11-07', 'verified', null, 'dress_socks', 'Sock-only facility: all guests must wear socks, and all children must wear non-slip grip socks.', 1);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
