insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-010:policy:booking_rule:4')::uuid, 'PE-010', 'https://www.kidzatplay.ca/', '2026-11-07', 'verified', null, 'booking_rule', 'The venue recommends buying tickets online in advance; on-site tickets may be limited or unavailable.', 4);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-010:policy:food_rule:5')::uuid, 'PE-010', 'https://www.kidzatplay.ca/contact', '2026-11-07', 'verified', null, 'food_rule', 'Outside food is allowed if it''s nut-free, and it must be eaten in the party rooms or the lounge. Cakes, cupcakes, loot bags and gifts aren''t allowed in the lounge; book a party room for any celebration.', 5);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
