insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-010:policy:other:7')::uuid, 'PE-010', 'https://www.kidzatplay.ca/events-and-specials', '2026-11-07', 'verified', null, 'other', 'Happy Hour, Saturday and Sunday 9 AM–12 PM: 1 adult included with each paid child admission. Only for tickets bought for 9–12; arriving after 12 voids it.', 7);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
