insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-010:policy:restriction:9')::uuid, 'PE-010', 'https://www.kidzatplay.ca/contact', '2026-11-07', 'verified', null, 'restriction', 'No alcohol. No piñatas, sparklers, confetti or glitter.', 9);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-010:policy:party:10')::uuid, 'PE-010', 'https://www.kidzatplay.ca/book-a-party', '2026-11-07', 'verified', null, 'party', 'Every birthday package includes a 2-hour private room plus 15 minutes of setup, tables, chairs and a 6 ft x 6 ft backdrop stand, free play for the birthday child, and a party helper and cleanup. The play area is shared with others. Bring your own nut-free food, drinks, tableware and decor.', 10);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-010:policy:party:11')::uuid, 'PE-010', 'https://www.kidzatplay.ca/book-a-party', '2026-11-07', 'verified', null, 'party', 'The party date and time must be approved by management before the booking is confirmed.', 11);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-010:policy:party:12')::uuid, 'PE-010', 'https://www.kidzatplay.ca/book-a-party', '2026-11-07', 'verified', null, 'party', 'Private parties hold up to 140 guests, with weekday, weekend and after-hours options; ask for pricing with the request form.', 12);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-010:policy:party:13')::uuid, 'PE-010', 'https://www.kidzatplay.ca/book-a-party', '2026-11-07', 'verified', null, 'party', 'Extras: helium balloon bouquets from $27 + tax, and character visits from $80 + tax per character.', 13);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-010:policy:party:14')::uuid, 'PE-010', 'https://www.kidzatplay.ca/events-and-specials', '2026-11-07', 'verified', null, 'party', 'Weeknight bonus: book a party Monday to Friday (5–7, 5:30–7:30 or 6–8 PM) and it''s upgraded to a private party free, with a free 30-Day Play Pass (up to 6 visits in 30 days, public play sessions only).', 14);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-010:policy:party:15')::uuid, 'PE-010', 'https://www.kidzatplay.ca/contact', '2026-11-07', 'verified', null, 'party', 'Children can''t keep playing after a party ends, because the venue has to control capacity.', 15);

